ac1.command:
set -u
# ac1 - THE STAMP IS MEASURED, NOT QUOTED. Read-only against the repository.
# The companion record must describe the index that is CHECKED OUT today, and it must
# prove it by being reproducible: every stamp value is re-derived here with hashlib
# (sha1 over the git blob header + CR-normalized bytes - the same recipe the auditor
# uses, so no git subprocess is needed anywhere), and every observation is re-derived
# from a fresh auditor run. A record whose stamp was copied from a WAL line or a
# groom note would pass inspection and fail this fence.
test -f docs/state/outputs/t107_record_stamp_findings.json || { echo "ac1 RED: docs/state/outputs/t107_record_stamp_findings.json missing - the stamped companion record is this card's deliverable"; exit 1; }
test -f docs/tools/leg_path_pin_audit.py || { echo "ac1 RED: the auditor is missing - run this fence from the repository root"; exit 1; }
command -v python3 >/dev/null 2>&1 || { echo "ac1 RED: python3 is missing - this fence's validator is python3 by contract, with no skip path"; exit 1; }
python3 - <<'PYAC1' || exit 1
import hashlib, json, re, subprocess, sys
IDX = "docs/state/merge_test_index.json"
TOOL = "docs/tools/leg_path_pin_audit.py"
REC = "docs/state/outputs/t107_record_stamp_findings.json"
def fail(m):
    sys.stderr.write("ac1 RED: " + m + "\n"); raise SystemExit(1)
raw = open(REC, "rb").read()
if raw.endswith(b"\n"):
    fail("%s carries a trailing newline - records under docs/state/outputs/ are written newline-free by the t104 recipe and later cards byte-compare against that discipline" % REC)
try:
    rec = json.loads(raw.decode("utf-8"))
except Exception as exc:
    fail("%s does not parse (%s)" % (REC, exc))
for k in ("issue_id", "tool", "index", "leg_index_convention", "legs_scanned",
          "pinned_legs", "broken_pins", "index_stamp", "replay_contract",
          "path_pin_findings"):
    if k not in rec:
        fail("%s is missing the key '%s' - the t104/t106 record shape is the interface later cards read, and index_stamp/replay_contract are what THIS card adds" % (REC, k))
if rec["issue_id"] != "t107":
    fail("%s declares issue_id=%s, expected t107" % (REC, rec["issue_id"]))
if rec["leg_index_convention"] != "0-based array indices into the tests array; every leg reference also carries issue_id and ac (WAL 1240 W2)":
    fail("%s does not state the 0-based leg-index convention verbatim - WAL 1240 W2 binds every artifact of this phase" % REC)
# --- the stamp must equal a FRESH measurement of the worktree index ---
iraw = open(IDX, "rb").read()
inorm = iraw.replace(b"\r\n", b"\n")
h = hashlib.sha1()
h.update(b"blob %d\0" % len(inorm))
h.update(inorm)
blob_id = h.hexdigest()
sha256 = hashlib.sha256(inorm).hexdigest()
st = rec["index_stamp"]
for k in ("path", "git_blob_id", "sha256_cr_normalized", "bytes_cr_normalized", "normalization"):
    if k not in st:
        fail("index_stamp is missing '%s' - a stamp without the blob id, a second-hash digest, the byte length and the normalization statement is a claim, not a stamp" % k)
if st["git_blob_id"] != blob_id:
    fail("the record's index_stamp.git_blob_id is %s but the worktree index hashes to %s - the stamp was quoted or stale, and a stale stamp is exactly the disease this card cures" % (st["git_blob_id"], blob_id))
if st["sha256_cr_normalized"] != sha256:
    fail("the record's sha256_cr_normalized is %s but a fresh hash says %s" % (st["sha256_cr_normalized"], sha256[:64]))
if int(st["bytes_cr_normalized"]) != len(inorm):
    fail("the record's bytes_cr_normalized is %s but the normalized index is %d bytes" % (st["bytes_cr_normalized"], len(inorm)))
if "CRLF" not in st["normalization"] or "LF" not in st["normalization"]:
    fail("index_stamp.normalization does not state the CRLF->LF folding - under core.autocrlf=true the worktree bytes and the blob bytes differ, and a reader who hashes the wrong shape gets a false mismatch")
if "--against-record" not in rec["replay_contract"]:
    fail("replay_contract does not name --against-record - the contract and the instrument must point at each other or the stamp is decoration")
# --- the observations must reproduce against a fresh run on THIS index ---
p = subprocess.run(["python3", TOOL, "--index", IDX], capture_output=True, text=True)
if p.returncode != 0:
    fail("a fresh run of %s exited %d (stderr: %s) - the stamped record cannot be cross-checked against a tool that does not run" % (TOOL, p.returncode, (p.stderr or "").strip()[:140]))
out = (p.stdout or "").replace("\r\n", "\n")
PIN = re.compile(r"^leg_path_pin_audit: pin leg (\d+) issue=(\S+) ac=(\S+) path=(\S+) status=(\S+) via=(\S+)")
fresh = {}
for ln in out.split("\n"):
    m = PIN.match(ln)
    if m:
        fresh.setdefault(int(m.group(1)), set()).add((m.group(2), m.group(3), m.group(4), m.group(5), m.group(6)))
for key, pat in (("legs_scanned", r"^leg_path_pin_audit: legs_scanned=(\d+)$"),
                 ("pinned_legs", r"^leg_path_pin_audit: pinned_legs=(\d+)$"),
                 ("broken_pins", r"^leg_path_pin_audit: broken_pins=(\d+)$")):
    m = re.search(pat, out, re.M)
    if not m:
        fail("the fresh auditor run is missing the %s summary line (exact format)" % key)
    if int(rec[key]) != int(m.group(1)):
        fail("the record says %s=%s, a fresh run says %s - the stamped record must be REPRODUCIBLE from the shipped tool, not hand-written" % (key, rec[key], m.group(1)))
findings = rec["path_pin_findings"]
if sorted(int(e["leg_index"]) for e in findings) != sorted(fresh):
    fail("the record's leg set %s != the fresh run's %s - a stamped record describes EXACTLY the legs the auditor derives on its stamped index" % (sorted(int(e["leg_index"]) for e in findings), sorted(fresh)))
for e in findings:
    i = int(e["leg_index"])
    for k in ("leg_index", "issue_id", "ac", "literal_paths", "classification", "via", "per_path_status"):
        if k not in e:
            fail("the record's leg %d entry is missing '%s'" % (i, k))
    want = set()
    for pth, sub in e["per_path_status"].items():
        want.add((e["issue_id"], e["ac"], pth, sub["status"], sub["via"]))
    if want != fresh[i]:
        fail("leg %d: the record's per-path observations %s != the fresh run's %s - on the STAMPED index there must be zero disagreement; this is the ac4-replay honesty this card exists to buy" % (i, sorted(want), sorted(fresh[i])))
print("ac1 evidence: stamp measured fresh (blob %s, sha256 %s, %d normalized bytes); %d legs reproduce observation-for-observation against a fresh auditor run; pinned_legs=%s broken_pins=%s" % (blob_id[:12], sha256[:12], len(inorm), len(findings), rec["pinned_legs"], rec["broken_pins"]))
print("ac1 GREEN: THE STAMP IS MEASURED AND THE RECORD REPRODUCES - index_stamp equals a fresh hashlib measurement of the worktree index, every per-path observation matches a fresh auditor run on that same index, and the record states the 0-based convention and the --against-record replay contract")
PYAC1

ac2.command:
set -u
# ac2 - CUSTODY SURVIVES THE STAMP. Read-only. The option this card REJECTED was
# regenerating the t106 record; this fence is the proof that the rejection was real:
# both historical records are byte-identical to their blobs at a run-time-derived
