# candidate, its rejection reason and the acceptance. Never a main-tip literal.
test -f docs/tools/leg_path_pin_audit.py || { echo "ac2 RED: run this fence from the repository root"; exit 1; }
command -v python3 >/dev/null 2>&1 || { echo "ac2 RED: python3 is missing"; exit 1; }
python3 - <<'PYAC2' || exit 1
import hashlib, json, subprocess, sys
FROZEN = ["docs/state/outputs/t104_hygiene_findings.json",
          "docs/state/outputs/t106_checker_b64_findings.json"]
REC = "docs/state/outputs/t107_record_stamp_findings.json"
KEYS = ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY",
        "GIT_COMMON_DIR", "GIT_PREFIX")
def fail(m):
    sys.stderr.write("ac2 RED: " + m + "\n"); raise SystemExit(1)
def cr(b):
    return b.replace(b"\r\n", b"\n")
def env():
    return {k: v for k, v in os.environ.items() if k not in KEYS}
import os
def git(args):
    p = subprocess.run(["git"] + args, capture_output=True, env=env())
    return cr(p.stdout or b""), (p.stderr or b"").decode("utf-8", "replace"), p.returncode
def rev(spec):
    out, _, rc = git(["rev-parse", "--revs-only", spec])
    r = out.decode("utf-8", "replace").strip()
    return r if rc == 0 and r else ""
def merge_base(ref):
    if not rev(ref):
        return ""
    out, _, rc = git(["merge-base", ref, "HEAD"])
    b = out.decode("utf-8", "replace").strip()
    return b if rc == 0 and b else ""
def blob_at(rev_, path):
    probe, _, rc = git(["rev-parse", "--verify", "-q", "%s:%s" % (rev_, path)])
    if rc != 0 or not probe.strip():
        return None
    out, err, _ = git(["show", "%s:%s" % (rev_, path)])
    if not out:
        fail("blob %s:%s unreadable (%s)" % (rev_, path, err[:120]))
    return out
CANDIDATES = [("HEAD^ (the branch parent)", rev("HEAD^")),
              ("merge-base(main, HEAD)", merge_base("main")),
              ("merge-base(origin/main, HEAD)", merge_base("origin/main"))]
BASE = BASE_LABEL = ""
for label, cand in CANDIDATES:
    if BASE:
        print("ac2 evidence: base candidate %s -> %s not tested (base already resolved)" % (label, cand[:7] or "(none)"))
        continue
    if not cand:
        print("ac2 evidence: base candidate %s -> (none) rejected: unresolvable on this checkout" % label); continue
    _, _, rc = git(["merge-base", "--is-ancestor", cand, "HEAD"])
    if rc != 0:
        print("ac2 evidence: base candidate %s -> %s rejected: not an ancestor of HEAD" % (label, cand[:7])); continue
    if cand == rev("HEAD"):
        print("ac2 evidence: base candidate %s -> %s rejected: is HEAD itself" % (label, cand[:7])); continue
    BASE, BASE_LABEL = cand, label
    print("ac2 evidence: base candidate %s -> %s ACCEPTED (strict ancestor of HEAD)" % (label, cand[:7]))
if not BASE:
    fail("no base candidate is a strict ancestor of HEAD - the branch is not in the (base -> product) shape; name the shape and re-groom rather than guess")
for p in FROZEN:
    at = blob_at(BASE, p)
    if at is None:
        fail("%s does not exist at the derived base %s - it predates this card and must not have been deleted" % (p, BASE[:7]))
    if not os.path.isfile(p):
        fail("%s vanished from the tree while it exists at the base (%s)" % (p, BASE[:7]))
    w = cr(open(p, "rb").read())
    if cr(at) != w:
        fail("%s differs from its %s blob (base sha256 %s vs worktree %s) - t104/t106 custody is byte-frozen and this card REJECTED regenerating either record; rewriting a closed card's evidence is the W1 temptation this fence exists to catch" % (p, BASE[:7], hashlib.sha256(cr(at)).hexdigest()[:12], hashlib.sha256(w).hexdigest()[:12]))
    print("ac2 evidence: %s byte-identical to its %s blob (sha256 %s)" % (p, BASE[:7], hashlib.sha256(w).hexdigest()[:12]))
rec106 = json.loads(open("docs/state/outputs/t106_checker_b64_findings.json", "rb").read().decode("utf-8"))
if "index_stamp" in rec106:
    fail("the t106 record carries an index_stamp key - the historical record was NOT to be quietly upgraded; the stamped companion is a NEW file, and a frozen file that gained a key is not frozen")
rec = json.loads(open(REC, "rb").read().decode("utf-8"))
note = str(rec.get("supersedes_note", ""))
for needle in ("t104_hygiene_findings.json", "t106_checker_b64_findings.json"):
    if needle not in note:
        fail("supersedes_note does not name %s - the companion record must state, in its own bytes, which frozen records it complements and does not replace" % needle)
if "frozen" not in note.lower() or "complement" not in note.lower():
    fail("supersedes_note must say the historical records stay FROZEN and this record COMPLEMENTS them - 'supersedes' without that sentence reads as a license to rewrite history")
print("ac2 GREEN: CUSTODY INTACT - both historical records byte-identical to their %s blobs, the t106 record gained no stamp, and the companion record names the freeze in writing" % BASE[:7])
PYAC2

ac3.command:
set -u
# ac3 - THE W1 STORY, RE-DERIVED IN ONE FENCE. Read-only against the tracked tree;
# every mutation lands on a throwaway copy. Three facts, all measured HERE rather
# than quoted from the card:
#   (F1) walking `git log -- docs/state/merge_test_index.json` from HEAD and
#        replaying the shipped auditor against each historical index BLOB (written
#        to a throwaway file, classified against today's tree exactly as the
#        auditor does) finds at least one blob whose fresh observations reproduce
#        the t106 record leg-for-leg and path-for-path - so the record is TRUE of a
#        NAMED historical blob;
#   (F2) none of those reproducing blobs equals the blob of the index checked out
#        today - so the record is NOT a claim about today's index, and the stamp
#        (absent from it) is exactly the missing disclosure;
#   (F3) replaying the t106 record against HEAD's index measures a nonzero
#        observation mismatch - the drift is quantified here, not asserted.
# NO literal commit id and NO literal digest appears in this fence: the blob that
# reproduces the record is DISCOVERED, so the fence reads the same on any branch
# shape that carries the history.
test -f docs/tools/leg_path_pin_audit.py || { echo "ac3 RED: run this fence from the repository root"; exit 1; }
test -f docs/state/outputs/t106_checker_b64_findings.json || { echo "ac3 RED: the t106 record is missing"; exit 1; }
command -v python3 >/dev/null 2>&1 || { echo "ac3 RED: python3 is missing"; exit 1; }
