python3 - <<'PYAC3' || exit 1
import hashlib, json, os, re, subprocess, sys
IDX = "docs/state/merge_test_index.json"
TOOL = "docs/tools/leg_path_pin_audit.py"
REC106 = "docs/state/outputs/t106_checker_b64_findings.json"
TMP = os.environ["TMP"]
KEYS = ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY",
        "GIT_COMMON_DIR", "GIT_PREFIX")
PIN = re.compile(r"^leg_path_pin_audit: pin leg (\d+) issue=(\S+) ac=(\S+) path=(\S+) status=(\S+) via=(\S+)")
def fail(m):
    sys.stderr.write("ac3 RED: " + m + "\n"); raise SystemExit(1)
def env():
    return {k: v for k, v in os.environ.items() if k not in KEYS}
def git(args):
    p = subprocess.run(["git"] + args, capture_output=True, env=env())
    return (p.stdout or b"").replace(b"\r\n", b"\n"), (p.stderr or b"").decode("utf-8", "replace"), p.returncode
def blob_id(norm):
    h = hashlib.sha1(); h.update(b"blob %d\0" % len(norm)); h.update(norm)
    return h.hexdigest()
def observations(index_path):
    p = subprocess.run(["python3", TOOL, "--index", index_path], capture_output=True, text=True)
    if p.returncode != 0:
        return None
    out = (p.stdout or "").replace("\r\n", "\n")
    obs = {}
    for ln in out.split("\n"):
        m = PIN.match(ln)
        if m:
            obs.setdefault(int(m.group(1)), set()).add((m.group(2), m.group(3), m.group(4), m.group(5), m.group(6)))
    return obs
def record_observations(rec):
    obs = {}
    for e in rec["path_pin_findings"]:
        i = int(e["leg_index"])
        obs[i] = set()
        for pth, sub in e.get("per_path_status", {}).items():
            obs[i].add((e["issue_id"], e["ac"], pth, sub["status"], sub["via"]))
    return obs
rec106 = json.loads(open(REC106, "rb").read().decode("utf-8"))
want = record_observations(rec106)
head_norm = open(IDX, "rb").read().replace(b"\r\n", b"\n")
head_blob = blob_id(head_norm)
fresh_head = observations(IDX)
if fresh_head is None:
    fail("the shipped auditor exited nonzero on HEAD's index - nothing can be classified")
