drift = [(i, sorted(want[i] ^ fresh_head.get(i, set()))) for i in sorted(want) if want[i] != fresh_head.get(i, set())]
if not drift:
    fail("the t106 record's observations EQUAL a fresh replay on HEAD's index - either the historical drift this card documents has been repaired by some other card (re-groom against the new state) or the auditor stopped seeing the class; either way this fence's premise is gone and a green-by-vacuity fence is worse than none")
print("ac3 evidence: F3 - replaying the t106 record against HEAD's index (%s) mismatches on %d legs (quantified, not asserted)" % (head_blob[:12], len(drift)))
# F1/F2: walk the index's own history for a blob that reproduces the record.
out, err, rc = git(["log", "--format=%H", "--", IDX])
if rc != 0:
    fail("git log -- %s failed: %s" % (IDX, err[:160]))
commits = [c for c in out.decode("utf-8", "replace").split("\n") if c.strip()][:80]
reproducers = []
for c in commits:
    blob, err, rc = git(["show", "%s:%s" % (c, IDX)])
    if rc != 0 or not blob:
        continue
    norm = blob.replace(b"\r\n", b"\n")
    fx = os.path.join(TMP, "idx_%s.json" % c[:10])
    open(fx, "wb").write(norm)
    if observations(fx) == {k: set(v) for k, v in want.items()}:
        bid = blob_id(norm)
        reproducers.append((c[:8], bid))
