    fail("no index blob in the last %d index-changing commits reproduces the t106 record - the record would then be a snapshot of NO committed index state, which is a deeper problem than stamping and must reach the orchestrator, not be fenced around" % len(commits))
hist_commit, hist_blob = reproducers[0]
if hist_blob == head_blob:
    fail("the reproducing blob IS HEAD's blob - then the t106 record would be true of today's index and F3's mismatch would be unexplained; the two facts cannot both hold, so the fence's premise broke")
print("ac3 evidence: F2 - the reproducing blob %s (commit %s) differs from HEAD's index blob %s - the record is a snapshot of a NAMED historical state, which is exactly what its missing stamp failed to say" % (hist_blob[:12], hist_commit, head_blob[:12]))
